{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요구 기능과 하중, 조립·가공 조건을 부품 설계에 반영하는 능력을 검증한다. 감속기 축 설계 과제에서 축 지름을 선택한 근거를 판단 초점으로 삼아, 하중 경로와 조립 상대 부품을 설계 결정에 연결했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업 과제에서 교재에 주어진 하중 조건으로 축 지름과 베어링을 선정하고 손도면과 계산서를 제출한 상황.",
          "task": "축의 요구 기능과 하중을 파악하고, 베어링 등 조립 상대 부품과 가공 조건을 고려해 축의 형상과 재질, 주요 치수를 정하는 것.",
          "action": "축에 작용하는 하중과 전달 경로를 해석해 지름 선정 근거를 설명하고, 상대 부품과의 조립 및 가공 조건을 형상·재질·주요 치수 결정에 반영한 내용을 제시한다.",
          "result": "선정한 축 지름과 형상·재질이 요구 기능 및 하중 조건에 부합하고, 조립 상대 부품과 가공 조건을 고려한 설계임을 손도면과 계산서의 내용으로 설명한다."
        },
        "expectedEvidence": [
          "축 지름을 선택한 근거를 주어진 하중과 하중 경로에 연결한 설명",
          "축의 요구 기능과 작용 하중을 파악한 내용",
          "베어링 등 조립 상대 부품과 가공 조건을 설계에 반영한 내용",
          "축의 형상·재질·주요 치수 결정과 그 이유를 하중 경로 및 조립 상대 부품에 연결한 설명"
        ]
      },
      "question": "‘기계요소설계 수업 과제: 감속기 축 설계 계산’에서 교재에 주어진 하중 조건으로 축 지름을 정하셨을 때, 그 지름을 선택한 근거는 무엇이었나요?",
      "answerTip": "답변할 내용을 짧게 정리한 뒤 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "축 지름을 정한 계산이나 판단을 구체적으로 제시하고, 작용 하중이 축과 상대 부품으로 전달되는 경로에 연결해 설명한다.",
            "축의 요구 기능과 하중 조건을 명확히 짚고, 베어링 등 상대 부품과의 조립 및 가공 조건이 설계에 미친 영향을 설명한다.",
            "최종 형상·재질·주요 치수와 선정 이유를 제시하고, 손도면과 계산서에 반영한 내용으로 설계 결정의 일관성을 보여준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "축 지름의 선정 근거를 하중이나 계산 결과와 연결하지만, 하중 경로 또는 상대 부품과의 관계에 대한 설명이 일반적이다.",
            "요구 기능과 하중은 설명하나, 조립·가공 조건의 반영이나 형상·재질·주요 치수의 선정 이유 중 일부가 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "축 지름을 선택한 근거를 제시하지 못하거나, 교재의 값을 따랐다는 설명에 그쳐 하중과의 관계를 확인할 수 없다.",
            "설계 결정을 요구 기능, 하중 경로, 조립 상대 부품과 연결하지 못하고 수업 소감이나 일반적인 설계 지식만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "3D 모델을 제작 가능한 양산용 2D 도면으로 정리하는 능력을 검증한다. 기능과 조립 조건을 근거로 치수 공차를 좁힐 대상을 고르는 기준을 판단 초점으로 삼고, 치수 공차·기하 공차·표면 처리 지정까지 확인한다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 감속기 축의 3D 모델을 양산용 2D 도면으로 정리하며 베어링 조립 조건을 맞춰야 하는 가정 상황.",
          "task": "기능에 필요한 치수에만 좁은 공차를 적용하고, 치수 공차와 기하 공차 및 표면 처리를 지정해 가공·조립 담당자가 제작할 수 있는 도면을 작성하는 것.",
          "action": "베어링과 결합하는 부위의 기능 및 조립 요구를 기준으로 좁은 치수 공차가 필요한 대상을 구분하고, 필요한 기하 공차와 표면 처리를 도면에 명시하는 방안을 제시한다.",
          "result": "기능상 필요한 부위에는 적절한 공차가 적용되고 나머지 부위에는 불필요하게 좁은 공차가 부여되지 않으며, 가공·조립 담당자가 필요한 조건을 도면에서 확인할 수 있을 것으로 예상한다."
        },
        "expectedEvidence": [
          "기능과 베어링 조립 요구를 근거로 치수 공차를 좁힐 대상을 고르는 기준",
          "3D 모델의 기능상 필요한 치수와 그 외 치수를 구분해 치수 공차를 지정하는 방안",
          "기능과 조립에 필요한 기하 공차 및 표면 처리를 지정하는 방안",
          "가공·조립 담당자가 그대로 제작할 수 있도록 필요한 치수와 공차, 표면 처리 조건을 2D 도면에 명시하는 방안"
        ]
      },
      "question": "입사 후 감속기 축의 3D 모델을 양산용 2D 도면으로 정리하면서 베어링 조립 조건을 맞춰야 한다면, 치수 공차를 좁힐 대상을 고르는 기준은 무엇인가요?",
      "answerTip": "생각을 정리한 뒤 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "베어링과 결합하는 부위의 기능 및 조립 요구를 구체적으로 들어 좁은 치수 공차가 필요한 대상의 선정 기준을 설명한다.",
            "기능에 직접 영향을 주는 치수와 그 외 치수를 구분하고, 모든 치수의 공차를 일괄적으로 좁히지 않는 지정 방안을 제시한다.",
            "필요한 기하 공차와 표면 처리의 적용 부위를 설명하고, 가공·조립 담당자가 제작 조건을 확인할 수 있는 2D 도면의 기재 내용과 예상 결과를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기능이나 베어링 조립과 관련된 치수의 공차를 좁혀야 한다는 기준은 제시하지만, 적용 대상이나 그 이유가 일반적이다.",
            "치수 공차를 구분하는 방안은 설명하나, 기하 공차·표면 처리 지정 또는 제작 가능한 도면의 기재 내용 중 일부가 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "공차를 좁힐 대상의 선정 기준을 설명하지 못하거나, 기능 및 조립 요구와 관계없이 모든 치수에 좁은 공차를 적용한다고 답한다.",
            "모델을 도면으로 변환한다는 설명에 그치거나 도구 조작만 설명해, 공차와 표면 처리 조건을 갖춘 제작용 도면 작성 방안을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}
